        "steps": [
          "Tap “Start Recording” on Home, or the microphone in a note's top bar.",
          "The first time, the system asks for microphone permission — allow it.",
          "While recording, a live waveform appears at the top and anything you write is aligned to the audio.",
          "Need a break? Tap “Pause Recording”. Tap “Resume Recording” to continue, and “Finish Recording” when you want to save and end it.",
          "When you stop, the recording appears under “Recent Recordings & Transcripts” on Home.",
          "During playback, tap a line of transcript to jump to the ink written at that time — and the other way round.",
          "To place a recording on a page: inside a notebook choose “More → Insert Recording”, or on the home screen use “⋯ → Insert into Notebook” on the recording row.",
          "Select a recording card on the page and tap “Transcribe Audio” at its top left. Kairumo turns the audio into editable tap-to-write text placed under the card for immediate editing.",
          "Supports “Audio-Ink Sync” karaoke playback: during playback, strokes written at that exact moment glow dynamically in sync with the audio; tap any stroke on the canvas to immediately seek the recording to that stroke’s timestamp.",
          "**Whisper speech-recognition engine**: the home screen may show a \"Download Whisper Model\" banner. Tap it to download the on-device Whisper model (a few hundred MB). Once installed, transcription accuracy improves significantly — all inference runs locally and your audio never leaves the device. The banner only appears if no compatible engine is already present.",
          "The transcript's script follows the interface language: with the Traditional Chinese interface, results are always converted to Traditional characters (speech engines often return Simplified); other languages are left as they are."
        ],
        "tip": "Recording and transcription both run on this device; nothing is uploaded. Transcription needs an on-device engine, and **not every device has one** — without it recording still works, but the recordings list has no transcript text and a recording card may not be able to produce transcribed text.",
        "fig": "home",
